import type { XYChartData } from '../types/xy-chart.js';

export function getValueByAccessor(dataItem: XYChartData, accessor: string) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  let value = dataItem as any;
  const keys = accessor.split('.');
  for (const key of keys) {
    if (value[key] !== undefined) {
      value = value[key];
    } else {
      return undefined;
    }
  }

  return value;
}
